  function signed(value){value=Number(value)||0;return(value>0?'+':'')+value;}
  function enemyVitalModel(name){var projection=builderProjection('enemy'),base=name==='hp'?Number(projection.hp)||1:name==='ac'?Number(projection.ac)||0:Number(projection.initiative)||0,min=name==='hp'?1:name==='ac'?0:-20,max=name==='hp'?999:99,adjustments=state.enemyVitalAdjustments||{},adjustment=Number(adjustments[name])||0,value=Math.max(min,Math.min(max,base+adjustment));return{name:name,base:base,adjustment:value-base,value:value,min:min,max:max,projection:projection};}
