  function enemyForm(){return'<form class="zg-arena-form-card" data-arena-form="enemy"><section>'+racePortrait(state.enemyRace,'hero')+'<span><b>'+esc(text('Свой противник','Свій противник'))+'</b><small>'+esc(text('Пресет: гуманоид второго уровня. Настройте расу, уровень и характеристики; предметы и заклинания выдаются через сумку.','Пресет: гуманоїд другого рівня. Налаштуйте расу, рівень і характеристики; предмети й закляття видаються через сумку.'))+'</small></span></section><label class="zg-arena-field">'+esc(text('Имя','Ім’я'))+'<input name="name" required value="'+esc(text('Наёмник','Найманець'))+'"></label><div class="zg-arena-field-grid"><label class="zg-arena-field">'+esc(text('Раса','Раса'))+'<input type="hidden" name="race" value="'+esc(state.enemyRace)+'">'+customSelect('enemy-race',state.enemyRace,optionModel(raceNames(),state.enemyRace))+'</label><label class="zg-arena-field">'+esc(text('Уровень','Рівень'))+'<input type="hidden" name="level" value="'+state.enemyLevel+'">'+customSelect('enemy-level',String(state.enemyLevel),levelOptions())+'</label></div><div class="zg-arena-builder-heading"><b>'+esc(text('Характеристики','Характеристики'))+'</b><small>'+esc(text('Распределите доступные очки','Розподіліть доступні очки'))+'</small></div>'+statControls('enemy')+'<div class="zg-arena-builder-heading"><b>'+esc(text('Боевые параметры','Бойові параметри'))+'</b><small>'+esc(text('База масштабируется автоматически, правки сохраняются отдельно','База масштабується автоматично, правки зберігаються окремо'))+'</small></div>'+enemyVitals()+'<button class="zg-arena-primary" type="submit">'+esc(text('Разместить противника','Розмістити противника'))+'</button></form>';}
